1	import { Router, type Request } from "express";
2	import type { Db } from "@paperclipai/db";
3	import {
4	  issueGraphLivenessAutoRecoveryRequestSchema,
5	  patchInstanceExperimentalSettingsSchema,
6	  patchInstanceGeneralSettingsSchema,
7	} from "@paperclipai/shared";
8	import { forbidden } from "../errors.js";
9	import { validate } from "../middleware/validate.js";
10	import { heartbeatService, instanceSettingsService, logActivity } from "../services/index.js";
11	import { assertBoardOrgAccess, getActorInfo } from "./authz.js";
12	
13	function assertCanManageInstanceSettings(req: Request) {
14	  if (req.actor.type !== "board") {
15	    throw forbidden("Board access required");
16	  }
17	  if (req.actor.source === "local_implicit" || req.actor.isInstanceAdmin) {
18	    return;
19	  }
20	  throw forbidden("Instance admin access required");
21	}
22	
23	export function instanceSettingsRoutes(db: Db) {
24	  const router = Router();
25	  const svc = instanceSettingsService(db);
26	  const heartbeat = heartbeatService(db);
27	
28	  router.get("/instance/settings/general", async (req, res) => {
29	    // General settings (e.g. keyboardShortcuts) are readable by any
30	    // authenticated org member or instance admin. Only PATCH requires instance-admin.
31	    assertBoardOrgAccess(req);
32	    res.json(await svc.getGeneral());
33	  });
34	
35	  router.patch(
36	    "/instance/settings/general",
37	    validate(patchInstanceGeneralSettingsSchema),
38	    async (req, res) => {
39	      assertCanManageInstanceSettings(req);
40	      const updated = await svc.updateGeneral(req.body);
41	      const actor = getActorInfo(req);
42	      const companyIds = await svc.listCompanyIds();
43	      await Promise.all(
44	        companyIds.map((companyId) =>
45	          logActivity(db, {
46	            companyId,
47	            actorType: actor.actorType,
48	            actorId: actor.actorId,
49	            agentId: actor.agentId,
50	            runId: actor.runId,
51	            action: "instance.settings.general_updated",
52	            entityType: "instance_settings",
53	            entityId: updated.id,
54	            details: {
55	              general: updated.general,
56	              changedKeys: Object.keys(req.body).sort(),
57	            },
58	          }),
59	        ),
60	      );
61	      res.json(updated.general);
62	    },
63	  );
64	
65	  router.get("/instance/settings/experimental", async (req, res) => {
66	    // Experimental settings are readable by any authenticated org member
67	    // or instance admin. Only PATCH requires instance-admin.
68	    assertBoardOrgAccess(req);
69	    res.json(await svc.getExperimental());
70	  });
71	
72	  router.patch(
73	    "/instance/settings/experimental",
74	    validate(patchInstanceExperimentalSettingsSchema),
75	    async (req, res) => {
76	      assertCanManageInstanceSettings(req);
77	      const updated = await svc.updateExperimental(req.body);
78	      const actor = getActorInfo(req);
79	      const companyIds = await svc.listCompanyIds();
80	      await Promise.all(
81	        companyIds.map((companyId) =>
82	          logActivity(db, {
83	            companyId,
84	            actorType: actor.actorType,
85	            actorId: actor.actorId,
86	            agentId: actor.agentId,
87	            runId: actor.runId,
88	            action: "instance.settings.experimental_updated",
89	            entityType: "instance_settings",
90	            entityId: updated.id,
91	            details: {
92	              experimental: updated.experimental,
93	              changedKeys: Object.keys(req.body).sort(),
94	            },
95	          }),
96	        ),
97	      );
98	      res.json(updated.experimental);
99	    },
100	  );
101	
102	  router.post(
103	    "/instance/settings/experimental/issue-graph-liveness-auto-recovery/preview",
104	    validate(issueGraphLivenessAutoRecoveryRequestSchema),
105	    async (req, res) => {
106	      assertCanManageInstanceSettings(req);
107	      res.json(await heartbeat.buildIssueGraphLivenessAutoRecoveryPreview({
108	        lookbackHours: req.body.lookbackHours,
109	      }));
110	    },
111	  );
112	
113	  router.post(
114	    "/instance/settings/experimental/issue-graph-liveness-auto-recovery/run",
115	    validate(issueGraphLivenessAutoRecoveryRequestSchema),
116	    async (req, res) => {
117	      assertCanManageInstanceSettings(req);
118	      const actor = getActorInfo(req);
119	      const result = await heartbeat.reconcileIssueGraphLiveness({
120	        runId: actor.runId,
121	        force: true,
122	        lookbackHours: req.body.lookbackHours,
123	      });
124	      const companyIds = await svc.listCompanyIds();
125	      await Promise.all(
126	        companyIds.map((companyId) =>
127	          logActivity(db, {
128	            companyId,
129	            actorType: actor.actorType,
130	            actorId: actor.actorId,
131	            agentId: actor.agentId,
132	            runId: actor.runId,
133	            action: "instance.settings.issue_graph_liveness_auto_recovery_run",
134	            entityType: "instance_settings",
135	            entityId: "default",
136	            details: {
137	              lookbackHours: result.lookbackHours,
138	              escalationsCreated: result.escalationsCreated,
139	              existingEscalations: result.existingEscalations,
140	              skippedOutsideLookback: result.skippedOutsideLookback,
141	              escalationIssueIds: result.escalationIssueIds,
142	            },
143	          }),
144	        ),
145	      );
146	      res.json(result);
147	    },
148	  );
149	
150	  return router;
151	}
